TLM.f("Commune/C3b",{"officium":"Commune plurimorum martirum extra Tempus Paschale: Salus autem","rule":[],"sections":{"Introitus":[{"k":"ref","la":"Ps 36:39"},{"k":"text","la":"Salus autem justórum a Dómino: et protéctor eórum est in témpore tribulatiónis."},{"k":"ref","la":"Ps 36:1"},{"k":"text","la":"Noli æmulári in malignántibus: neque zeláveris faciéntes iniquitátem."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Salus autem justórum a Dómino: et protéctor eórum est in témpore tribulatiónis."}],"Oratio":[{"k":"text","la":"Deus, qui nos ánnua sanctórum Mártyrum tuorum N. et N. sollemnitáte lætíficas: concéde propítius; ut, quorum gaudémus méritis, accendámur exémplis."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Hebrǽos"},{"k":"ref","la":"Hebr 10:32-38"},{"k":"text","la":"Fratres: Rememorámini prístinos dies, in quibus illumináti magnum certámen sustinuístis passiónum: et in áltero quidem oppróbriis et tribulatiónibus spectáculum facti: in áltero autem sócii táliter conversántium effécti. Nam et vinctis compássi estis, et rapínam bonórum vestrórum cum gáudio suscepístis, cognoscéntes vos habere meliórem et manéntem substántiam. Nolíte itaque amíttere confidéntiam vestram, quæ magnam habet remuneratiónem. Patiéntia enim vobis necéssaria est: ut, voluntátem Dei faciéntes, reportétis promissiónem. Adhuc enim módicum aliquántulum, qui ventúrus est, véniet, et non tardábit. Justus autem meus ex fide vivit."}],"Graduale":[{"k":"ref","la":"Ps 33:18-19"},{"k":"text","la":"Clamavérunt justi, et Dóminus exaudívit eos: et ex ómnibus tribulatiónibus eórum liberávit eos."},{"k":"text","la":"Juxta est Dóminus his, qui tribuláto sunt corde: et húmiles spíritu salvábit. Allelúja, allelúja.","mark":"V"},{"k":"text","la":"Te Mártyrum candidátus laudat exércitus, Dómine. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Ps 33:18-19"},{"k":"text","la":"Clamavérunt justi, et Dóminus exaudívit eos: et ex ómnibus tribulatiónibus eórum liberávit eos."},{"k":"text","la":"Juxta est Dóminus his, qui tribuláto sunt corde: et húmiles spíritu salvábit.","mark":"V"},{"k":"ref","la":"Ps 125:5-6"},{"k":"text","la":"Qui séminant in lácrimis, in gáudio metent."},{"k":"text","la":"Eúntes ibant et flébant, mitténtes sémina sua.","mark":"V"},{"k":"text","la":"Veniéntes autem vénient cum exsultatióne, portántes manípulos suos.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 12:1-8"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Atténdite a ferménto pharisæórum, quod est hypócrisis. Nihil autem opértum est, quod non revelétur: neque abscónditum, quod non sciátur. Quóniam, quæ in ténebris dixístis, in lúmine dicéntur: et quod in aurem locúti estis in cubículis, prædicábitur in tectis. Dico autem vobis amícis meis: Ne terreámini ab his, qui occídunt corpus, et post hæc non habent ámplius quid fáciant. Osténdam autem vobis, quem timeátis: timéte eum, qui postquam occíderit, habet potestátem míttere in gehénnam. Ita dico vobis: hunc timéte. Nonne quinque pásseres véneunt dipóndio, et unus ex illis non est in oblivióne coram Deo? Sed et capílli cápitis vestri omnes numeráti sunt. Nolíte ergo timére: multis passéribus pluris estis vos. Dico autem vobis: Omnis, quicúmque conféssus fúerit me coram homínibus, et Fílius hóminis confitébitur illum coram Angelis Dei."}],"Offertorium":[{"k":"ref","la":"Sap 3:1-3"},{"k":"text","la":"Justórum ánimæ in manu Dei sunt, et non tanget illos torméntum malítiae: visi sunt óculis insipiéntium mori: illi autem sunt in pace, allelúja."}],"Secreta":[{"k":"text","la":"Oblátis, quǽsumus, Dómine, placáre munéribus: et, intercedéntibus sanctis Martýribus tuis N. et N., a cunctis nos defénde perículis."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 10:27"},{"k":"text","la":"Quod dico vobis in ténebris, dícite in lúmine, dicit Dóminus: et quod in aure audítis, prædicáte super tecta."}],"Postcommunio":[{"k":"text","la":"Hæc nos commúnio, Dómine, purget a crímine: et, intercedéntibus sanctis Martýribus tuis N. et N., coeléstis remédii fáciat esse consórtes."},{"k":"macro","name":"Per Dominum"}]},"hr":{"be7e83b3647261b8":{"t":"Ps 36, 39, Ps 36, 1\n(Ps 36, 39) Spasenje pravednika dolazi od Gospodina. On je njihovo utočište u vrijeme nevolje. (Ps 36, 1) Nemoj zaviđati sreći zlotvora, niti se uznemiravati radi zadovoljstva grešnika.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 36, 39) Spasenje pravednika dolazi od Gospodina. On je njihovo utočište u vrijeme nevolje.","kn":"(Ps. 36, 39). U Gospodinu je spas pravednika; Gospodin je njihovo utočište u nevolji. (Ps. 36, 1) Misa »Štiti me« za mučenike Ne zaviđaj sreći grješnika i zlotvora! Slava Ocu . . . U Gospodinu ...","knRef":"Kniewald 1942, str. 800–801 (snimka 401) (OCR)"},"bc4fefc2074c9a04":{"kn":"Dopusti, milostivi Bože, koji nas razveseljuješ godišnjom svetkovinom Tvojih svetih mučenika I. i I., da nas rasplamte njihovi primjeri, kao što nas razveseljuju njihove zasluge.\n<i>Po G. n.</i>","knRef":"Kniewald 1942, str. 802"},"e1975ee9d370e316":{"t":"Heb 10, 32-38\nČitanje Poslanice bl. Pavla apostola Hebrejima. Braćo, sjetite se onih prvih dana, kada ste prosvijetljeni podnijeli teške borbe i patnje. Sad ste bili izloženi pogrdama i nevoljama, sad opet postali dionicima onih, koji su već doživjeli isto. Vi ste bili milosrdni prema zatočenicima i vedro gledajući podnijeli ste kada su vam otimali vaša dobra, jer ste znali da imate bolji i trajni imutak. Stoga ne gubite pouzdanje, za koje ćete primiti obilnu nagradu. Treba vam strpljivosti, da vršeći Božju volju postignete obećanje. Da, još vrlo malo i doći će onaj koji ima doći i neće zakasniti. A moj pravednik živi od vjere.","kn":"Čitanje poslanice bi. Pavla apostola Hebrejima (10, 32-38). Braćo! Sjetite se onih prvih dana, kad ste prosvijetljeni (podnijeli tešku borbu patnja. Amo ste bili izloženi pogrdama i nevoljama, a tamo ste postali sudionicima onih, koji su isto doživjeli. Vi ste bili samilosni prema zatočenicima i s radošću ste podnijeli, kad su oteli vaša dobra, jer ste znali, da imate bolji i trajni imetak. Zato ne odbacujte svoga pouzdanja, koje će biti obilno nagrađeno. Treba vam strpljivosti, da postignete obećanje vršeći volju Božju. Jer još nešto malo i doći će onaj, koji ima doći, i ne će kasniti. A moj pravednik živi od vjere.","knRef":"Kniewald 1942, str. 802–803 (snimka 402) (OCR)"},"20fe01eb04b0f5d5":{"t":"Ps 33, 18-19\nZavapiše pravednici i Gospodin ih usliša, i izbavi ih iz svih nevolja njihovih. Gospodin je blizu onima koji su skrušena srca. On spašava ponizne duhom.\n\n<i>Aleluja</i>, <i>aleluja</i>.\nTebe, Gospodine, hvali svjetla vojska mučenika. <i>Aleluja</i>.","kn":"(Ps. 33, 18, 19). Zavapiše pravednici i Gospodin ih je uslišao i izbavio ih je od svih nevolja. Blizu je Gospodin onima, koji su skrušena srca i spasit će one, koji su ponizni duhorn.\n\nAleluja, aleluja! Tebe, Gospodine, svijetla mučenička hvali vojiska, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 584–585 (snimka 293) (OCR)"},"fd132778da52f21b":{"t":"Lk 12, 1-8\nSlijedi sveto Evanđelje po Luki. U ono vrijeme reče Isus svojim učenicima: Čuvajte se farizejskog kvasca, to jest licemjerja. Ništa nije sakriveno što se ne bi otkrilo, ni tajno što se ne bi saznalo. Što ste govorili u tajnosti kazat će se na javnosti, a što ste šaptali u uho u sobama propovijedat će se na krovovima. A vama svojim prijateljima kažem: Ne bojte se onih koji ubijaju tijelo, a poslije toga ne mogu više ništa. Kazat ću vam koga se imate bojati: Bojte se onoga koji poslije smrti može baciti u pakao. Da, ponavljam: Njega se bojte! Zar se ne prodaje pet vrabaca za dva novčića? A ni jedan od njih nije zaboravljen kod Boga. A na vašoj su glavi sve vlasi izbrojane. Nemojte se, dakle, bojati, jer vi vrijedite više nego mnogo vrabaca. Kažem vam: Tko god prizna mene pred ljudima, priznat će i njega Sin Čovječji pred Božjim anđelima!","kn":"t Slijedi sveto evanđelje po Luki (12, 1-8). U ono vrijeme reče Isus svojim učenicima: Čuvajte se farizejskoga kvasca, to jest licemjera. Ništa nema sakrivena, što se ne će otkriti, niti tajna, što se ne će saznati. Jer što ste govorili u tajnosti, govorit će se na javi, i što ste na uho’ šaptali u sobama, razglasit će se na krovovima. A kažem vama, svojim prijateljima; Ne iplašite se onih, koji ubijaju tijelo, a poslije toga ne mogu učiniti više ništa. Kazat ču vam, koga se imate bojati: Bojte se onoga, koji kad ubije, može baciti u pakao. Da, kažem vam: Bojte se njega! Zar se ne prodaje pet vrabaca za dva novčića? A nijedan od njih nije zaboravljen pred Bogom. A na vašoj su glavi izbrojene sve vlasi. Nemojte se dakle bojati, jer vi vrijedite više nego mnogo vrabaca. Kažem vam: Svakoga, kojigod mene prizna pred ljudima, priznat će i Sin čovječji pred Božjim anđelima.","knRef":"Kniewald 1942, str. 610–611 (snimka 306) (OCR)"},"a7438b09133fada7":{"t":"Mudr 3, 1 i 2 i 3\nDuše su pravednika u Božjoj ruci, i neće ih se dotaći muka zlobnika; očima se luđaka činilo da umiru, a oni su u miru, <i>aleluja</i>.","kn":"(Mudr. 3, 1-3). Duše su pravednika u ruci Božjoj, i ne će ih se dotaći muka zlobe; činilo se luđačkim očima, da umirii, a oni su u miru. Aleluja.","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"41a508d61a5cbef6":{"t":"Ublaži se, molimo, Gospodine, prikaznim darovima i po zagovoru tvojih svetih mučenika brani nas od svih pogibelji.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","v":"∅ → n et n","kn":". Neka Te ublaže. Gospodine, prineseni darovi, da nas zagovorom Tvojih svetih mučenika I. i I. braniš od svih pogibli. Po G. n.","knRef":"Kniewald 1942, str. 802–803 (snimka 402) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"080d978e8249bb86":{"t":"Mt 10, 27\nŠto vam kažem u tami, razglasujte na svjetlu, kaže Gospodin, i ono što vam na uho šapćem, propovijedajte s krovova.","v":"aleluia → ∅","kn":"(Mt. 10, 27). Što vam govorim u tami, ka'Zujte na svjetlosti, veli Gosjpodin; i što na uho čujete, propovijedajte na krovovima.","knRef":"Kniewald 1942, str. 562–563 (snimka 282) (OCR)"},"d6a4f2922d2f46ac":{"kn":"Ova nas, Gospodine, pričest očistila od grijeha i zagovorom svetih mučenika I. i I. učinila dionicima nebeskog spasenja.\n<i>Po G. n.</i>","knRef":"Kniewald 1942, str. 803"}},"variants":{"paschal":{"Introitus":[{"k":"ref","la":"Ps 63:3"},{"k":"text","la":"Protexísti me, Deus, a convéntu malignántium, allelúja: a multitúdine operántium iniquitátem, allelúja, allelúja."},{"k":"ref","la":"Ps. 63:2"},{"k":"text","la":"Exáudi, Deus, oratiónem meam cum déprecor: a timóre inimíci éripe ánimam meam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Protexísti me, Deus, a convéntu malignántium, allelúja: a multitúdine operántium iniquitátem, allelúja, allelúja."}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Sap 5:1-5"},{"k":"text","la":"Stabunt justi in magna constántia advérsus eos, qui se angustiavérunt et qui abstulérunt labóres eórum. Vidéntes turbabúntur timore horríbili, et mirabúntur in subitatióne insperátæ salútis, dicéntes intra se, poeniténtiam agéntes, et præ angústia spíritus geméntes: Hi sunt, quos habúimus aliquándo in derísum et in similitúdinem impropérii. Nos insensáti vitam illórum æstimabámus insániam, et finem illórum sine honóre: ecce, quómodo computáti sunt inter fílios Dei, et inter Sanctos sors illórum est."}],"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: étenim veritátem tuam in ecclésia sanctórum. Allelúja."},{"k":"ref","la":"Ps 20:4"},{"k":"text","la":"Posuísti, Dómine, super caput ejus corónam de lápide pretióso. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joannes 15:1-7"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Ego sum vitis vera: et Pater meus agrícola est. Omnem pálmitem in me non feréntem fructum, tollet eum: et omnem, qui fert fructum, purgábit eum, ut fructum plus áfferat. Jam vos mundi estis propter sermónem, quem locútus sum vobis. Manéte in me: et ego in vobis. Sicut palmes non potest ferre fructum a semetípso, nisi mánserit in vite: sic nec vos, nisi in me manséritis. Ego sum vitis, vos pálmites: qui manet in me, et ego in eo, hic fert fructum multum: quia sine me nihil potéstis fácere. Si quis in me non mánserit, mittétur foras sicut palmes, et aréscet, et cólligent eum, et in ignem mittent, et ardet. Si manséritis in me, et verba mea in vobis mánserint: quodcúmque voluéritis, petétis, et fiet vobis."}],"Offertorium":[{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: et veritátem tuam in ecclésia sanctórum, allelúja, allelúja."}],"Communio":[{"k":"ref","la":"Ps 63:11"},{"k":"text","la":"Lætábitur justus in Dómino, et sperábit in eo: et laudabúntur omnes recti corde, allelúja, allelúja."}]}}});
